export const SCALE_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/scale-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getScaleStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(SCALE_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
